ALTER TABLE public.supplier_buy_orders ADD COLUMN quantity_choices integer[], ADD COLUMN stock_checks bigint NOT NULL DEFAULT 0, ADD COLUMN last_choices_checked integer[] NOT NULL DEFAULT '{}';
CREATE FUNCTION public.validate_supplier_buy_choices() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.quantity_choices IS NOT NULL AND (cardinality(NEW.quantity_choices)<>3 OR NEW.quantity_choices[1] IS NULL OR NEW.quantity_choices[2] IS NULL OR NEW.quantity_choices[3] IS NULL OR NEW.quantity_choices[1]<>NEW.target OR NEW.quantity_choices[1]>1000 OR NEW.quantity_choices[3]<1 OR NEW.quantity_choices[1]<=NEW.quantity_choices[2] OR NEW.quantity_choices[2]<=NEW.quantity_choices[3]) THEN RAISE EXCEPTION 'Invalid quantity choices'; END IF; RETURN NEW; END $$;
CREATE TRIGGER supplier_buy_choices_validate BEFORE INSERT OR UPDATE ON public.supplier_buy_orders FOR EACH ROW EXECUTE FUNCTION public.validate_supplier_buy_choices();
CREATE FUNCTION public.record_supplier_buy_check(p_order uuid,p_stock integer,p_choices integer[]) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF p_stock<0 THEN RETURN false; END IF; UPDATE public.supplier_buy_orders SET last_stock=p_stock,last_checked_at=now(),stock_checks=stock_checks+1,last_choices_checked=p_choices,message='' WHERE id=p_order AND status='watching'; RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.record_supplier_buy_check(uuid,integer,integer[]) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.record_supplier_buy_check(uuid,integer,integer[]) TO service_role;
CREATE OR REPLACE FUNCTION public.claim_supplier_buy_batch(p_order uuid,p_qty integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.supplier_buy_orders; b uuid; BEGIN SELECT * INTO o FROM public.supplier_buy_orders WHERE id=p_order FOR UPDATE; IF o.id IS NULL OR o.status<>'watching' OR p_qty<1 OR p_qty>o.target-o.acquired THEN RETURN NULL; END IF; IF o.quantity_choices IS NOT NULL AND (o.acquired<>0 OR NOT p_qty=ANY(o.quantity_choices) OR EXISTS(SELECT 1 FROM public.supplier_buy_batches WHERE buy_order_id=p_order AND (status='completed' OR (status='rejected' AND quantity<=p_qty)))) THEN RETURN NULL; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(o.supplier_id::text||':'||o.external_id,0)); IF NOT EXISTS(SELECT 1 FROM public.suppliers WHERE id=o.supplier_id AND is_enabled) THEN RETURN NULL; END IF; IF EXISTS(SELECT 1 FROM public.supplier_buy_batches b JOIN public.supplier_buy_orders old ON old.id=b.buy_order_id WHERE old.supplier_id=o.supplier_id AND old.external_id=o.external_id AND b.status IN ('submitted','unknown')) THEN RETURN NULL; END IF; INSERT INTO public.supplier_buy_batches(buy_order_id,quantity) VALUES(p_order,p_qty) RETURNING id INTO b; UPDATE public.supplier_buy_orders SET status='purchasing',message='' WHERE id=p_order; RETURN b; END $$;
CREATE OR REPLACE FUNCTION public.finish_supplier_buy_batch(p_batch uuid,p_status text,p_items jsonb,p_supplier_order text,p_message text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.supplier_buy_batches; o public.supplier_buy_orders; n integer; BEGIN SELECT * INTO b FROM public.supplier_buy_batches WHERE id=p_batch; IF b.id IS NULL THEN RAISE EXCEPTION 'Batch unavailable'; END IF; SELECT * INTO o FROM public.supplier_buy_orders WHERE id=b.buy_order_id FOR UPDATE; SELECT * INTO b FROM public.supplier_buy_batches WHERE id=p_batch FOR UPDATE; IF b.status<>'submitted' THEN RETURN; END IF; IF p_status NOT IN ('completed','rejected','unknown') OR jsonb_typeof(p_items)<>'array' THEN RAISE EXCEPTION 'Invalid outcome'; END IF; n:=jsonb_array_length(p_items); IF n>b.quantity OR o.acquired+n>o.target THEN RAISE EXCEPTION 'Delivery count exceeds purchase'; END IF; IF p_status='rejected' AND n<>0 THEN RAISE EXCEPTION 'Rejected batch has delivery'; END IF; IF p_status='completed' AND n<>b.quantity THEN p_status:='unknown'; END IF; UPDATE public.supplier_buy_batches SET status=p_status,items=p_items,supplier_order_id=p_supplier_order,message=left(coalesce(p_message,''),300) WHERE id=p_batch; UPDATE public.supplier_buy_orders SET acquired=acquired+n,status=CASE WHEN o.status='cancelled' THEN 'cancelled' WHEN p_status='unknown' THEN 'review' WHEN p_status='completed' AND o.quantity_choices IS NOT NULL THEN 'completed' WHEN acquired+n=target THEN 'completed' WHEN o.status='paused' THEN 'paused' WHEN p_status='rejected' AND o.quantity_choices IS NOT NULL AND p_message='OUT_OF_STOCK' AND b.quantity>o.quantity_choices[3] THEN 'watching' WHEN p_status='rejected' THEN 'paused' ELSE 'watching' END,message=left(coalesce(p_message,''),300) WHERE id=o.id; END $$;
REVOKE ALL ON FUNCTION public.claim_supplier_buy_batch(uuid,integer),public.finish_supplier_buy_batch(uuid,text,jsonb,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_supplier_buy_batch(uuid,integer),public.finish_supplier_buy_batch(uuid,text,jsonb,text,text) TO service_role;